(2001, 'Exodus 20:13', 'Exodus', 20, 13, '&nbsp;قتل مۀ کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2002, 'Exodus 20:14', 'Exodus', 20, 14, '&nbsp;زنا مۀ کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2003, 'Exodus 20:15', 'Exodus', 20, 15, '&nbsp;غلا مۀ کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2004, 'Exodus 20:16', 'Exodus', 20, 16, '&nbsp;د چا خِلاف د دروغو ګواهى مۀ ورکوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2005, 'Exodus 20:17', 'Exodus', 20, 17, '&nbsp;د خپل ګاونډى د کور خواهش مۀ کوئ، د هغۀ د ښځې، د هغۀ د نوکرانو، د هغۀ د څاروو، خرونو او د هغه يو شى لالچ هم مۀ کوئ کوم چې ستاسو د ګاونډى وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2006, 'Exodus 20:18', 'Exodus', 20, 18, '&nbsp;چې کله خلقو د تندرونو او د بيګل آواز واورېدو او برېښناګانې او د غرۀ لوګى يې وليدل، هغوئ د يرې نه ولړزېدل او لرې ودرېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2007, 'Exodus 20:19', 'Exodus', 20, 19, '&nbsp;هغوئ موسىٰ ته ووئيل، ”کۀ تۀ زمونږ سره خبرې کوې نو مونږ به ورته غوږ ونيسو، خو کۀ خُدائ پاک زمونږ سره خبرې وکړى نو مونږ يريږو چې مړۀ به شو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2008, 'Exodus 20:20', 'Exodus', 20, 20, '&nbsp;موسىٰ ورته وفرمائيل، ”يرېږئ مه، خُدائ پاک خو صِرف دې له راغلے دے چې تاسو وآزمائى او خپله يره ستاسو په زړونو کښې واچوى چې تاسو ګناه نۀ کوئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2009, 'Exodus 20:21', 'Exodus', 20, 21, '&nbsp;خو خلق هم هغه شان لرې ولاړ وُو او صِرف موسىٰ هغه تکې تورې تيارې له نزدې ورَغلو چرته چې خُدائ پاک وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2010, 'Exodus 20:22', 'Exodus', 20, 22, '&nbsp;بيا مالِک خُدائ موسىٰ ته حُکم وکړو چې، ”بنى اِسرائيلو ته ووائى، تاسو وليدل چې ما مالِک خُدائ ستاسو سره د آسمان نه څنګه خبرې کړې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2011, 'Exodus 20:23', 'Exodus', 20, 23, '&nbsp;د خپلو ځانونو دپاره د سپينو زرو يا د سرو زرو بُتان مۀ جوړَوئ چې زما په ځائ د هغوئ عبادت وکړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2012, 'Exodus 20:24', 'Exodus', 20, 24, '&nbsp;زما دپاره د خاورې نه يوه قربان‌ګاه جوړه کړئ او په دې باندې خپل ګډان، چېلى او غوَيان د پوره سوزېدونکې قربانو او د سلامتۍ د قربانو په توګه حلالوئ. د خپل عبادت دپاره کوم ځائ چې زۀ درته وښايم نو هغه ځائ ته به زۀ تاسو له درځم او برکت به درکوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2013, 'Exodus 20:25', 'Exodus', 20, 25, '&nbsp;کۀ تاسو زما دپاره د کاڼو نه يوه قربان‌ګاه جوړَوئ، نو هغه د تراشلے شوى کاڼو نه مۀ جوړَوئ، ځکه چې کله تاسو په هغه کاڼو آوزار لګوئ، نو هغه به ناپاکه کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2014, 'Exodus 20:26', 'Exodus', 20, 26, '&nbsp;زما دپاره داسې قربان‌ګاه مۀ جوړَوئ چې تاسو بره په پوړو ورخېژئ، ګنې ستاسو د سَتر اندامونه به بربنډ شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2015, 'Exodus 21:1', 'Exodus', 21, 1, '&nbsp;”د بنى اِسرائيلو دپاره دا قانون مقرر کړه چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2016, 'Exodus 21:2', 'Exodus', 21, 2, '&nbsp;کۀ تاسو يو عبرانے غلام واخلئ، هغه به شپږ کاله ستاسو خِدمت کوى. او په اوؤم کال به بغېر د څۀ څيز درکولو نه آزاد شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2017, 'Exodus 21:3', 'Exodus', 21, 3, '&nbsp;چې کله هغه د وادۀ نه مخکښې ستاسو غلام شوے وى، نو د آزادېدو په وخت به د ځان سره ښځه نۀ بوځى، خو چې کله هغه ستاسو غلام کېدلو او وادۀ يې کړے وو، نو هغه خپله ښځه د ځان سره بوتلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2018, 'Exodus 21:4', 'Exodus', 21, 4, '&nbsp;کۀ مالِک ورله وادۀ وکړى او د هغۀ زامن يا لوڼه پېدا شى، نو هغه ښځه او د هغۀ بچى به د مالِک وى او هغه سړے چې آزاد کړے شى نو هغه يواځې تلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2019, 'Exodus 21:5', 'Exodus', 21, 5, '&nbsp;خو کۀ غلام صفا ووائى چې زۀ د خپل مالِک سره، خپلې ښځې او خپلو بچو سره مينه لرم او آزادېدل نۀ غواړم،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2020, 'Exodus 21:6', 'Exodus', 21, 6, '&nbsp;نو خپل مالِک به هغه د قاضيانو ځائ ته بوځى. هلته به يې د دروازې يا چوکاټ په مخکښې ودروى او په ستن دې د هغۀ په غوږ کښې سورے وکړى. نو ټول عُمر به يې غلام وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2021, 'Exodus 21:7', 'Exodus', 21, 7, '&nbsp;کۀ يو سړے خپله لور د وينځې په توګه خرڅه کړى، نو هغه به د نرانو نوکرانو په شان نۀ شى آزادولے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2022, 'Exodus 21:8', 'Exodus', 21, 8, '&nbsp;کۀ هغه په يو داسې کس خرڅه کړے شى چې هغه يې د ښځې کولو اراده لرى، خو د هغۀ دا خوښه نۀ وى، نو خپل پلار به دا واپس اخلى، د هغې مالِک دا په پردو خلقو نۀ شى خرڅولے، ځکه چې هغۀ د دې سره ټګى کړې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2023, 'Exodus 21:9', 'Exodus', 21, 9, '&nbsp;کۀ يو سړے د خپل زوئ دپاره وينځه واخلى، نو هغه به د هغې سره د لور په شان سلوک کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2024, 'Exodus 21:10', 'Exodus', 21, 10, '&nbsp;کۀ يو سړے دوېمه ښځه وکړى، نو هغه به خامخا د خپلې وړومبۍ ښځې د مخکښې په شان د هغې د خوراک، جامو او د وادۀ د حقُونو خيال ساتى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2025, 'Exodus 21:11', 'Exodus', 21, 11, '&nbsp;کۀ هغه ورسره دا درې ذمه وارۍ نۀ پوره کوى، نو هغه به يې خامخا بغېر د څۀ قيمت نه آزاده کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2026, 'Exodus 21:12', 'Exodus', 21, 12, '&nbsp;چې څوک يو کس ووهى او هغه وهلے شوے کس مړ شى نو هغه وهونکے به خامخا وژلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2027, 'Exodus 21:13', 'Exodus', 21, 13, '&nbsp;خو کۀ دا د خُدائ پاک نه راپېښه شوې وى او هغۀ دا قصداً نۀ وى وژلے، نو هغه به د پناه دپاره يو داسې ځائ ته وتښتى چې کوم درته زۀ ښايم او هلته به په پناه کښې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2028, 'Exodus 21:14', 'Exodus', 21, 14, '&nbsp;خو کۀ يو کس غصه شى او قصداً بل څوک قتل کړى، نو هغه به خامخا وژلے شى، تر دې پورې کۀ هغه زما قربان‌ګاه ته هم د پناه دپاره تښتېدلے وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2029, 'Exodus 21:15', 'Exodus', 21, 15, '&nbsp;چې څوک هم خپل پلار يا خپله مور ووهى نو هغه به خامخا وژلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2030, 'Exodus 21:16', 'Exodus', 21, 16, '&nbsp;کۀ څوک يو کس اغوا کړى او بيا يې خرڅ کړى يا يې د ځان سره وساتى، نو هغه اغواکار به خامخا وژلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2031, 'Exodus 21:17', 'Exodus', 21, 17, '&nbsp;هر څوک چې خپل مور پلار ته بدرد وائى هغه دې قتل کړے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2032, 'Exodus 21:20', 'Exodus', 21, 20, '&nbsp;کۀ يو کس خپله وينځه يا خپل غلام په کوتک ووهى او هغه هم په هغه ځائ مړ شى، نو مالِک له به يې خامخا سزا ورکولے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2033, 'Exodus 21:21', 'Exodus', 21, 21, '&nbsp;خو کۀ وهلے شوے کس يوه يا دوه ورځې ژوندے وى، نو مالِک له به يې سزا نۀ شى ورکولے، ځکه چې هغه يې خپل تاوان وو نو دا سزا يې بس ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2034, 'Exodus 21:22', 'Exodus', 21, 22, '&nbsp;کۀ څۀ کسان په جګړه وى او يوه اُميدواره ښځه ووهى او چې د هغې اولاد وغورزيږى، خو بل ځائ يې زخمى نۀ وى، نو چا چې هغه وهلى وى هغه به دومره جرمانه کيږى چې څومره جرمانه د هغې ښځې خاوند غواړى او چې قاضيان ووائى چې دا جرمانه صحيح ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2035, 'Exodus 21:23', 'Exodus', 21, 23, '&nbsp;خو کۀ هغه ښځه په خپله هم زخمى وى، نو سزا به د ژوند په بدل کښې ژوند وى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2036, 'Exodus 21:24', 'Exodus', 21, 24, '&nbsp;د سترګې په بدل کښې سترګه، او د غاښ په بدل کښې غاښ، د لاس په بدل کښې لاس، د پښې په بدل کښې پښه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2037, 'Exodus 21:25', 'Exodus', 21, 25, '&nbsp;د سوزولو په بدل کښې سوزول، د زخم په بدل کښې زخم، د کوړو په بدل کښې کوړې وهل دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2038, 'Exodus 21:26', 'Exodus', 21, 26, '&nbsp;کۀ يو کس د خپل غلام يا خپلې وينځې په وهلو سره سترګه وباسى، نو د سترګې په بدل کښې به هغه غلام يا وينځه آزادولے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2039, 'Exodus 21:27', 'Exodus', 21, 27, '&nbsp;کۀ هغه د خپل غلام يا وينځې غاښ مات کړى، نو د غاښ په بدل کښې به هغه غلام يا وينځه آزادولے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2040, 'Exodus 21:28', 'Exodus', 21, 28, '&nbsp;کۀ يو غوَيے څوک په ښکر ووهى او هغه مړ شى، نو هغه غوَيے به خامخا سنګسارولے شى او د دې غوښه به نۀ شى خوړلے، خو د غوَيى مالِک خلاص دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2041, 'Exodus 21:29', 'Exodus', 21, 29, '&nbsp;خو کۀ دې غوَيى مخکښې هم خلق وهل او مالِک له يې خبردارے ورکړے شوے وى او هغۀ دا غوَيے تړلے نۀ وى ساتلے او دا څوک ووهى او مړ شى، نو غوَيے به سنګسارولے شى او مالِک به يې هم وژلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2042, 'Exodus 21:30', 'Exodus', 21, 30, '&nbsp;خو کۀ د مالِک نه د خپل ژوند بچ کولو تاوان وغوښتلے شى، نو هغه به پوره تاوان ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2043, 'Exodus 21:31', 'Exodus', 21, 31, '&nbsp;کۀ يو غوَيے هلک يا جينۍ ووژنى، نو هم دغه شان فېصله به پرې کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2044, 'Exodus 21:32', 'Exodus', 21, 32, '&nbsp;کۀ غوَيے يو غلام يا وينځه ووژنى، نو د غوَيى مالِک به د هغه غلام يا وينځې مالِک له د سپينو زرو دېرش سيکې ورکوى او غوَيے به هم سنګسارولے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2045, 'Exodus 21:33', 'Exodus', 21, 33, '&nbsp;کۀ يو کس يوه کنده کولاو پرېږدى يا کنده وکنى او دا پټه نۀ کړى او يو غوَيے يا خر ورغورزيږى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2046, 'Exodus 21:34', 'Exodus', 21, 34, '&nbsp;نو هغه کس به خامخا د دې ځناور مالِک ته تاوان ورکوى. هغه به يې مالِک ته د دې قيمت ورکړى او هغه مړ ځناور به د هغۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2047, 'Exodus 21:35', 'Exodus', 21, 35, '&nbsp;کۀ د يو کس غوَيے د بل چا غوَيے ووهى او هغه مړ شى، نو هغوئ دواړه دې هغه ژوندے غوَيے خرڅ کړى او هغه پېسې دې په خپلو کښې تقسيم کړى، او هغه مړ ځناور دې هم په خپلو کښې تقسيم کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2048, 'Exodus 21:36', 'Exodus', 21, 36, '&nbsp;خو کۀ دا پته لګېدلې وى چې دې غوَيى مخکښې هم وهل کول او مالِک دا تړلے نۀ ساتلو، نو هغه به د غوَيى په تاوان کښې هغه بل کس له ژوندے غوَيے ورکوى او هغه مړ ځناور به د هغۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2049, 'Exodus 22:1', 'Exodus', 22, 1, '&nbsp;کۀ يو کس يوه غوا يا ګډه پټه کړى او حلاله يې کړى يا يې خرڅه کړى، هغه به خامخا د يوې غوا په بدل کښې پينځۀ غواګانې ورکوى او د يوې ګډې په بدل کښې به څلور ګډې ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2050, 'Exodus 22:5', 'Exodus', 22, 5, '&nbsp;کۀ يو کس خپل څاروى په يو پټى يا د انګورو په باغ کښې څروى او دا خوشے لاړ شى او د بل چا په پټى کښې فصل وخورى، نو هغه به خامخا په تاوان کښې د خپل پټى يا د انګورو باغ نه د ټولو نه ښۀ پېداوار ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2051, 'Exodus 22:6', 'Exodus', 22, 6, '&nbsp;کۀ څوک په خپل پټى کښې اور ولګوى او اور د واښو په ذريعه د بل چا پټى ته ورسيږى او د هغۀ ګېډۍ شوے، رېبلے شوے، يا داسې فصل وسوزوى چې ولاړ وى، چا چې دا اور لګولے وى هغه به يې پوره تاوان ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2052, 'Exodus 22:7', 'Exodus', 22, 7, '&nbsp;کۀ يو کس د بل چا پېسې يا قيمتى څيزونه د امانت په توګه د هغۀ دپاره کېږدى او د هغۀ د کور نه غلا وشى او هغه غل ونيولے شى نو يو په دوه به ترې نه اخستلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2053, 'Exodus 22:8', 'Exodus', 22, 8, '&nbsp;خو کۀ غل ونۀ نيولے شى، نو د چا سره چې امانت پروت وو هغه به خامخا د قاضيانو په مخکښې حاضر شى او هلته به قسم وکړى چې دغه پردے مال دۀ پخپله نۀ دے پټ کړے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2054, 'Exodus 22:9', 'Exodus', 22, 9, '&nbsp;د مال او سامان هر قِسم لانجې، کۀ هغه د څاروو، خرونو، ګډو، جامو، يا د بل ورک شوى څيز په حقله وى، چې دوه کسان په کښې دعوىٰ لرى هغوئ دې خپلې لانجې د قاضيانو په مخکښې پېش کوى. هغوئ چې چا ته پړ ووائى نو هغه به هغه بل ته يو په دوه ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2055, 'Exodus 22:10', 'Exodus', 22, 10, '&nbsp;کۀ يو کس بل کس له خپل خر، غوا، ګډه يا بل څاروے امانت ورکړى او هغه مړ يا زخمى شى يا په داسې وخت کښې وتښتولے شى چې هيڅ څوک يې هم ونۀ وينى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2056, 'Exodus 22:11', 'Exodus', 22, 11, '&nbsp;نو هغه کس به ورته د مالِک خُدائ په نوم قسم کوى چې د هغه بل کس ځناور يې نۀ دے پټ کړے. کۀ هغه ځناور چا نۀ وى پټ کړے، نو هغه مالِک دې دا قسم ومنى او تاوان ورکولو ته ضرورت نشته،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2057, 'Exodus 22:12', 'Exodus', 22, 12, '&nbsp;خو کۀ ځناور چا پټ کړے وى، نو هغه کس به خامخا مالِک ته د هغې تاوان ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2058, 'Exodus 22:13', 'Exodus', 22, 13, '&nbsp;خو کۀ هغه ځنګلى ځناور وژلے وى، نو هغه کس به د هغې پاتې حِصه د ثبوت دپاره راوړى، نو هغۀ له د هغه ځناور د تاوان ورکولو ضرورت نشته کوم چې ځنګلى ځناورو وژلے وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2059, 'Exodus 22:14', 'Exodus', 22, 14, '&nbsp;کۀ يو کس د بل کس نه يو څاروے وغواړى او هغه په داسې وخت کښې زخمى يا مړ شى چې مالِک يې موجود نۀ وى، نو هغه به يې خامخا تاوان ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2060, 'Exodus 22:15', 'Exodus', 22, 15, '&nbsp;خو کۀ دا کار په داسې وخت کښې شوے وى چې مالِک يې حاضر وى، نو هغۀ ته د تاوان ورکولو ضرورت نشته. کۀ ځناور يې په مزدورۍ راوستلے وى، نو هغه به صِرف د مزدورۍ پېسې په تاوان کښې ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2061, 'Exodus 22:16', 'Exodus', 22, 16, '&nbsp;کۀ يو سړے يوه پېغله دوکه کړى چې هغه کوژدن شوې هم نۀ وى او د هغې سره څملى، هغه دې خامخا د هغې حق مهر ورکړى نو ښځه به يې شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2062, 'Exodus 22:17', 'Exodus', 22, 17, '&nbsp;خو کۀ پلار يې هغۀ له د ورکولو نه اِنکار وکړى، نو هغه به خامخا د هغې پېغلې پلار له د حق مهر برابر قيمت ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2063, 'Exodus 22:18', 'Exodus', 22, 18, '&nbsp;کومه ښځه چې کوډې کوى هغه ژوندۍ مۀ پرېږدئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2064, 'Exodus 22:19', 'Exodus', 22, 19, '&nbsp;هغه کس به خامخا وژلے شى کوم چې د ځناور سره زنا وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2065, 'Exodus 22:20', 'Exodus', 22, 20, '&nbsp;څوک چې د مالِک خُدائ نه بغېر بل خُدائ ته قربانى پېش کوى هغه دې هلاک کړے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2066, 'Exodus 22:21', 'Exodus', 22, 21, '&nbsp;د يو مسافر سره بد سلوک يا زياتے مۀ کوئ، هغه راياد کړئ چې تاسو په خپله د مِصر په مُلک کښې مسافر وئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2067, 'Exodus 22:22', 'Exodus', 22, 22, '&nbsp;د کونډې يا يتيم سره بد سلوک مۀ کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2068, 'Exodus 22:23', 'Exodus', 22, 23, '&nbsp;کۀ تاسو د هغوئ سره بد سلوک وکړو او چې کله هغوئ ما مالِک خُدائ ته د مدد دپاره فرياد وکړى نو زۀ به د هغوئ فرياد اورم،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2069, 'Exodus 22:24', 'Exodus', 22, 24, '&nbsp;او زۀ به په قهر شم او تاسو به په جنګ ووژنم. ستاسو ښځې به کونډې شى او ستاسو بچى به يتيمانان شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2070, 'Exodus 22:25', 'Exodus', 22, 25, '&nbsp;کۀ تاسو زما د خلقو نه يو کس له قرض ورکړئ چې هغه غريب وى، د هغۀ سره د يو قرض ورکوونکى په شان عمل مۀ کوئ او سود ترې نه مۀ غواړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2071, 'Exodus 22:26', 'Exodus', 22, 26, '&nbsp;کۀ تاسو د قرض په ضمانت کښې د چا نه چُوغه واخلئ، دا به تاسو د نمرپرېواتو نه مخکښې هغۀ له واپس ورکوئ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2072, 'Exodus 22:27', 'Exodus', 22, 27, '&nbsp;ځکه چې د هغۀ سره د ځان پټولو دپاره صرف يوه چُوغه وه، د دې نه بغېر هغه په څۀ کښې اودۀ شى؟ چې کله هغه ما ته سوال زارى وکړى، زۀ به د هغۀ فرياد اورم ځکه چې زۀ رحيم يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2073, 'Exodus 22:28', 'Exodus', 22, 28, '&nbsp;د خُدائ پاک په حق کښې بدې ردې مۀ وايئ او د خپل قوم مشرانو ته ښېرې مۀ کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2074, 'Exodus 22:29', 'Exodus', 22, 29, '&nbsp;خپله غله، مے او خپل د زيتُونو تېل ما ته ښۀ په وخت پېش کوئ. تاسو خپل مشران زامن ما له راکړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2075, 'Exodus 22:30', 'Exodus', 22, 30, '&nbsp;تاسو د خپلو څاروو او د خپلو ګډو وړومبى پېدا شوى بچى ما ته وقف کړئ. هر يو وړومبے پېدا شوے نر بچے به اووۀ ورځې د خپلې مور سره ايساريږى او په اتمه ورځ به هغه ما ته پېش کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2076, 'Exodus 22:31', 'Exodus', 22, 31, '&nbsp;تاسو به زما مقدس خلق يئ، نو د داسې ځناور غوښه مۀ خورئ چې هغه ځنګلى ځناور وژلے وى، هغه سپو ته اچوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2077, 'Exodus 23:1', 'Exodus', 23, 1, '&nbsp;د دروغو خبر مۀ خوروئ او د دروغو ګواهۍ په ذريعه د يو مجرم کس مدد مۀ کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2078, 'Exodus 23:2', 'Exodus', 23, 2, '&nbsp;د ډېرو خلقو په بد عمل کښې يا د قانون ماتولو په ګواهۍ کښې ملګرتيا مۀ کوئ او بې‌اِنصافى مۀ کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2079, 'Exodus 23:3', 'Exodus', 23, 3, '&nbsp;په يوه مقدمه کښې د يو غريب سړى ناجائزه طرفدارے مۀ کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2080, 'Exodus 23:4', 'Exodus', 23, 4, '&nbsp;کۀ تاسو د خپل دشمن غوا يا خر ووينئ چې لار يې غلطه کړې وى، نو هغۀ له يې خامخا واپس ورولئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2081, 'Exodus 23:5', 'Exodus', 23, 5, '&nbsp;کۀ د هغۀ خر ووينئ چې د بار لاندې پرېوتلے وى، نو د خر په پاڅولو کښې د هغۀ مدد وکړئ، او ځان پرې مۀ ناغرضه کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2082, 'Exodus 23:6', 'Exodus', 23, 6, '&nbsp;چې کله يو غريب سړے په عدالت کښې حاضر شى نو د هغۀ سره بې‌اِنصافى مۀ کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2083, 'Exodus 23:7', 'Exodus', 23, 7, '&nbsp;د دروغو اِلزام مۀ لګوئ او يو صادق او بې‌ګناه سړے مۀ وژنئ، ځکه چې څوک داسې بد عمل وکړى نو زۀ به هغه نۀ پرېږدم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2084, 'Exodus 23:8', 'Exodus', 23, 8, '&nbsp;رشوت مۀ اخلئ، ځکه چې رشوت بينا خلق ړندوى او حق نۀ ګورى او رشوت د صادقانو په خبرو کښې هم چالاکى پېدا کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2085, 'Exodus 23:9', 'Exodus', 23, 9, '&nbsp;د يو مسافر سره بد سلوک مۀ کوئ، تاسو ته پته ده چې د يو مسافر په زړۀ څۀ تېريږى، ځکه چې تاسو هم د مِصر په مُلک کښې مسافر وئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2086, 'Exodus 23:10', 'Exodus', 23, 10, '&nbsp;شپږ کاله خپله زمکه کَرئ او فصل ترې نه رېبئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2087, 'Exodus 23:11', 'Exodus', 23, 11, '&nbsp;خو په اوؤم کال يې شاړه پرېږدئ او چې څۀ په کښې شوى وى هغه ترې نه مۀ رېبئ، چې څۀ په کښې پاتې وى نو هغه به غريبانان خلق او ځنګلى ځناور وخورى. د انګورو او زيتُونو د باغونو سره هم دغه شان وکړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2088, 'Exodus 23:12', 'Exodus', 23, 12, '&nbsp;په هفته کښې شپږ ورځې کار کوئ، خو په اوومه ورځ کار مۀ کوئ، د دې دپاره چې ستاسو غلامان او هغه مسافر چې ستاسو دپاره کار کوى او داسې ستاسو څاروى به هم آرام وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2089, 'Exodus 23:13', 'Exodus', 23, 13, '&nbsp;چې ما مالِک خُدائ تاسو ته څۀ وئيلى دى په هغې عمل کوئ. د نورو معبودانو عبادت مۀ کوئ او نۀ چې ستاسو د خولې نه د هغوئ د نومونو ذکر واورم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2090, 'Exodus 23:14', 'Exodus', 23, 14, '&nbsp;زما د درناوى دپاره په کال کښې درې ځله اختر کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2091, 'Exodus 23:15', 'Exodus', 23, 15, '&nbsp;چې ما څنګه حُکم درکړے دے هم هغه شان د ابيب په مياشت کښې، تاسو د پتيرې روټۍ اختر کوئ، دا هغه مياشت ده چې تاسو په کښې د مِصر نه راووتلئ. د دې اختر په اووۀ ورځو کښې تاسو پتيره روټۍ خورئ. او هيڅ څوک به هم زما په حضور کښې خالى لاسونه نۀ حاضريږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2092, 'Exodus 23:16', 'Exodus', 23, 16, '&nbsp;چې کله تاسو خپل فصلونه رېبل شروع کوئ، نو د لَو کولو اختر کوئ په خپلو پټو کښې چې تاسو کوم تخم کَرلے وى نو د هغه فصل وړومبے پېداوار پېش کوئ او چې کله تاسو خپل فصل د پټو نه راټول کړئ نو په خزان کښې د فصل راټولولو اختر کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2093, 'Exodus 23:17', 'Exodus', 23, 17, '&nbsp;هر کال په دې درېو اخترونو کښې دې خامخا ستاسو ټول نران مالِک خُدائ ستاسو د خُدائ پاک عبادت له راځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2094, 'Exodus 23:18', 'Exodus', 23, 18, '&nbsp;چې کله تاسو يو ځناور قربانى کوئ او د هغۀ وينه ما ته پېش کوئ نو خمبيره روټۍ ورسره مۀ پېش کوئ. په دې اخترونو کښې چې کوم ځناور ما ته قربانى شى د هغوئ وازګه دې د سحر پورې نۀ شى پرېښودلے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2095, 'Exodus 23:19', 'Exodus', 23, 19, '&nbsp;هر کال د مالِک خُدائ ستاسو خُدائ پاک، کور ته د خپلې زمکې نه رېبلے شوې وړومبۍ غله راوړئ. د چېلۍ بچے د خپلې مور په پيو کښې مۀ پخوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2096, 'Exodus 23:20', 'Exodus', 23, 20, '&nbsp;ګورئ، زۀ به ستاسو نه وړاندې يوه فرښته درولېږم چې په لار کښې ستاسو حِفاظت کوى او هغه ځائ ته مو راولى کوم چې ما تيار کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2097, 'Exodus 23:21', 'Exodus', 23, 21, '&nbsp;هغې ته پام کوئ او د هغې خبرې ته غوږ نيسئ. د هغې خِلاف بغاوت مۀ کوئ، ځکه چې هغې له مې پوره اختيار ورکړے دے او هغه به ستاسو بغاوت معاف نۀ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2098, 'Exodus 23:22', 'Exodus', 23, 22, '&nbsp;خو کۀ تاسو په رښتيا سره د هغې خبره ومنئ او هغه هر څۀ وکړئ چې ما حُکم درکړے دے، نو زۀ به ستاسو د دشمنانو سخت دشمن يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2099, 'Exodus 23:23', 'Exodus', 23, 23, '&nbsp;زما فرښته به ستاسو په وړاندې روانه وى او تاسو به د اموريانو، حِتيانو، فرزيانو، کنعانيانو، حِويانو او د يبوسيانو مُلک ته بوځى او زۀ به هغوئ تباه کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2100, 'Exodus 23:24', 'Exodus', 23, 24, '&nbsp;د هغوئ معبودانو ته سجده مۀ لګوئ او مۀ يې عبادت کوئ او د هغوئ طريقې مۀ خپلوئ او د هغوئ بُتان مات کړئ او د هغوئ د کاڼو مقدسې ستنې وغورزوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');